fn bytes(hex: &str) -> Vec<u8> {
    let hex = format!("{}{hex}", "0".repeat(hex.len() % 2));
    (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
        .collect()
}

fn integer(hex: &str) -> PaddedBigUint {
    let Ok(value) = PaddedBigUint::from_be(&bytes(hex));
    value
}

/// BC 測試以 `FixedSecureRandom` 固定的 k。
struct FixedK(PaddedBigUint);

impl DsaKCalculator<PaddedBigUint> for FixedK {
    fn init(&mut self, _: &PaddedBigUint, _: &PaddedBigUint, _: &[u8]) {}

    fn next_k(&mut self) -> PaddedBigUint {
        self.0.clone()
    }
}

fn keys(params: DsaParameters, x: &str) -> (DsaPublicKey, DsaPrivateKey) {
    let p = NonZero::new(params.p().clone()).unwrap();
    let y = params.g().mod_pow(&integer(x), &p);
    (
        DsaPublicKey::new(y, params.clone()),
        DsaPrivateKey::new(integer(x), params),
    )
}

/// 以固定的 k 簽 `message`，比對 (r, s)，再以公鑰驗證。
fn known_answer(params: DsaParameters, x: &str, k: &str, message: &[u8], r: &str, s: &str) {
    let (public_key, private_key) = keys(params, x);
    let mut signer = DsaSigner::new(FixedK(integer(k)));
    signer.init(&private_key).unwrap();
    let signature = signer.generate_signature(message).unwrap();
    assert_eq!(signature, (integer(r), integer(s)));
    let mut verifier = DsaSigner::new(FixedK(integer("01")));
    verifier.init(&public_key).unwrap();
    assert!(
        verifier
            .verify_signature(message, &signature.0, &signature.1)
            .unwrap()
    );
    assert!(
        !verifier
            .verify_signature(&[0; 20], &signature.0, &signature.1)
            .unwrap()
    );
}

#[test]
fn the_basic_fips_186_2_vector_matches_bouncy_castle() {
    // BC 以 k2 為 h 產生 g = h^((p − 1) / q) mod p，以同一份 keyData 作為 x 與 k。
    let (p, q) = (integer(BASIC_P), integer(BASIC_Q));
    let big = |value: &PaddedBigUint| BigUint::from(value.clone());
    let e = (big(&p) - 1u32) / &big(&q);
    let h = big(&integer(BASIC_K2));
    let g = PaddedBigUint::from(h.mod_pow(&e, &NonZero::new(big(&p)).unwrap()));
    known_answer(
        DsaParameters::new(p, q, g),
        BASIC_KEY,
        BASIC_KEY,
        &bytes(BASIC_MESSAGE),
        BASIC_R,
        BASIC_S,
    );
}

#[test]
fn the_four_fips_186_3_vectors_match_bouncy_castle() {
    for (p, q, g, x, k, message, r, s) in [
        (
            DSA2_1_P,
            DSA2_1_Q,
            DSA2_1_G,
            DSA2_1_X,
            DSA2_1_K,
            DSA2_1_MESSAGE,
            DSA2_1_R,
            DSA2_1_S,
        ),
        (
            DSA2_2_P,
            DSA2_2_Q,
            DSA2_2_G,
            DSA2_2_X,
            DSA2_2_K,
            DSA2_2_MESSAGE,
            DSA2_2_R,
            DSA2_2_S,
        ),
        (
            DSA2_3_P,
            DSA2_3_Q,
            DSA2_3_G,
            DSA2_3_X,
            DSA2_3_K,
            DSA2_3_MESSAGE,
            DSA2_3_R,
            DSA2_3_S,
        ),
        (
            DSA2_4_P,
            DSA2_4_Q,
            DSA2_4_G,
            DSA2_4_X,
            DSA2_4_K,
            DSA2_4_MESSAGE,
            DSA2_4_R,
            DSA2_4_S,
        ),
    ] {
        let params = DsaParameters::new(integer(p), integer(q), integer(g));
        known_answer(params, x, k, &bytes(message), r, s);
    }
}

fn rfc_6979<D: Digest + Clone>(
    digest: D,
    params: DsaParameters,
    x: &str,
    message: &[u8],
) -> (PaddedBigUint, PaddedBigUint) {
    let mut hasher = digest.clone();
    hasher.update(message);
    let mut hash = vec![0; hasher.digest_size()];
    hasher.do_final(&mut hash);
    let (public_key, private_key) = keys(params, x);
    let mut signer = DsaSigner::new(HMacDsaKCalculator::new(digest.clone()));
    signer.init(&private_key).unwrap();
    let signature = signer.generate_signature(&hash).unwrap();
    let mut verifier = DsaSigner::new(HMacDsaKCalculator::new(digest));
    verifier.init(&public_key).unwrap();
    assert!(
        verifier
            .verify_signature(&hash, &signature.0, &signature.1)
            .unwrap()
    );
    signature
}

#[test]
fn the_twenty_rfc_6979_dsa_vectors_match() {
    let params = |index| match index {
        1 => (
            DsaParameters::new(integer(RFC_1_P), integer(RFC_1_Q), integer(RFC_1_G)),
            RFC_1_X,
        ),
        _ => (
            DsaParameters::new(integer(RFC_2_P), integer(RFC_2_Q), integer(RFC_2_G)),
            RFC_2_X,
        ),
    };
    for (index, digest, message, r, s) in RFC_CASES {
        let (params, x) = params(index);
        let signature = match digest {
            "Sha1Digest" => rfc_6979(Sha1Digest::new(), params, x, message),
            "Sha224Digest" => rfc_6979(Sha224Digest::new(), params, x, message),
            "Sha256Digest" => rfc_6979(Sha256Digest::new(), params, x, message),
            "Sha384Digest" => rfc_6979(Sha384Digest::new(), params, x, message),
            _ => rfc_6979(Sha512Digest::new(), params, x, message),
        };
        assert_eq!(signature, (integer(r), integer(s)), "{index} {digest}");
    }
}

#[test]
fn dsa_digest_signer_signs_a_message_end_to_end() {
    let params = DsaParameters::new(integer(RFC_2_P), integer(RFC_2_Q), integer(RFC_2_G));
    let (public_key, private_key) = keys(params, RFC_2_X);
    let dsa = || DsaSigner::new(HMacDsaKCalculator::new(Sha256Digest::new()));
    let mut signer = DsaDigestSigner::with_encoding(dsa(), Sha256Digest::new(), PlainDsaEncoding);
    signer.init(&private_key).unwrap();
    signer.update(b"sample").unwrap();
    let mut signature = vec![0; signer.max_signature_size()];
    let length = signer.generate_signature(&mut signature).unwrap();
    // RFC 6979 A.2.2，SHA-256 與 "sample"。
    let expected = RFC_CASES
        .iter()
        .find(|case| case.0 == 2 && case.1 == "Sha256Digest" && case.2 == b"sample")
        .unwrap();
    assert_eq!(
        signature[..length],
        [bytes(expected.3), bytes(expected.4)].concat()[..]
    );

    let mut verifier = DsaDigestSigner::with_encoding(dsa(), Sha256Digest::new(), PlainDsaEncoding);
    verifier.init(&public_key).unwrap();
    verifier.update(b"sample").unwrap();
    assert!(verifier.verify_signature(&signature[..length]).unwrap());
}

#[test]
fn errors_are_reported() {
    let params = DsaParameters::new(integer(RFC_1_P), integer(RFC_1_Q), integer(RFC_1_G));
    let (public_key, private_key) = keys(params.clone(), RFC_1_X);
    let mut signer = DsaSigner::new(FixedK(integer("01")));
    assert_eq!(
        signer.generate_signature(&[0; 20]),
        Err(DsaSignerError::NotInitialized)
    );
    signer.init(&public_key).unwrap();
    assert_eq!(
        signer.generate_signature(&[0; 20]),
        Err(DsaSignerError::NotForSigning)
    );
    signer.init(&private_key).unwrap();
    let one = PaddedBigUint::from(1u8);
    assert_eq!(
        signer.verify_signature(&[0; 20], &one, &one),
        Err(DsaSignerError::NotForVerifying)
    );
    assert_eq!(
        signer.init(&DsaPrivateKey::new(params.q().clone(), params.clone())),
        Err(DsaSignerError::InvalidKey(DsaError::InvalidPrivateKey))
    );
    assert_eq!(
        signer.init(&DsaPublicKey::new(PaddedBigUint::from(1u8), params.clone())),
        Err(DsaSignerError::InvalidKey(DsaError::InvalidPublicKey))
    );

    // r 與 s 要在 [1, q − 1]。
    let mut verifier = DsaSigner::new(FixedK(integer("01")));
    verifier.init(&public_key).unwrap();
    let zero = PaddedBigUint::from(0u8);
    for (r, s) in [
        (&zero, &one),
        (&one, &zero),
        (params.q(), &one),
        (&one, params.q()),
    ] {
        assert!(!verifier.verify_signature(&[0; 20], r, s).unwrap());
    }
}
